const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const clean=(v,n=200)=>typeof v==='string'?v.trim().slice(0,n):'';
const uuid=v=>typeof v==='string'&&/^[a-f0-9-]{36}$/i.test(v);
const now=()=>new Date().toISOString();
const hex=b=>[...b].map(v=>v.toString(16).padStart(2,'0')).join('');
const hash=async v=>hex(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v))));
async function input(r){const s=await r.text();if(s.length>600000)throw Error('Request too large');return JSON.parse(s);}
function amount(v,max=10000000){if(!Number.isFinite(v)||v<0||v>max)throw Error('Check amount');return Math.round(v*100);}
export function invoiceTotals(v){
 if(!Array.isArray(v.items)||!v.items.length||v.items.length>60)throw Error('Add 1–60 items');
 const tax=Number(v.tax??13);if(!Number.isFinite(tax)||tax<0||tax>30)throw Error('Check tax percentage');
 const items=v.items.map(i=>{const quantity=Number(i.quantity),price=Number(i.price);if(!Number.isFinite(quantity)||quantity<=0||quantity>100000||!clean(i.description,500))throw Error('Check item description and quantity');return {name:clean(i.name,160),description:clean(i.description,500),quantity,price:amount(price)/100,taxable:i.taxable!==false,lineTotal:Math.round(quantity*amount(price))};});
 const subtotal=items.reduce((s,i)=>s+i.lineTotal,0);if(subtotal>1000000000)throw Error('Invoice total is too large');
 const discount=v.discount||{type:'percent',value:0},deposit=v.deposit||{type:'percent',value:50};
 for(const s of [discount,deposit])if(!['percent','fixed'].includes(s.type)||!Number.isFinite(s.value)||s.value<0||s.value>(s.type==='percent'?100:10000000))throw Error('Check discount and deposit');
 const discountAmount=Math.min(subtotal,discount.type==='percent'?Math.round(subtotal*discount.value/100):amount(discount.value));
 const net=subtotal-discountAmount,taxable=items.filter(i=>i.taxable).reduce((s,i)=>s+i.lineTotal,0),taxAmount=Math.round((subtotal?taxable*net/subtotal:0)*tax/100),total=net+taxAmount,depositAmount=Math.min(total,deposit.type==='percent'?Math.round(total*deposit.value/100):amount(deposit.value));
 return {items,tax,subtotal,discount,discountAmount,net,taxAmount,total,deposit,depositAmount,currency:'CAD'};
}
async function summary(db,row,publicView=false){const d=JSON.parse(row.data),payments=(await db.prepare('SELECT id,amount,method,reference,created_at FROM invoice_payments WHERE document_id = ? ORDER BY created_at').bind(row.id).all()).results;const paid=payments.reduce((s,p)=>s+p.amount,0),balance=Math.max(0,d.total-paid),depositAmount=d.depositAmount??d.total;return {id:row.id,status:row.status==='cancelled'?'cancelled':balance===0?'paid':paid?'partially_paid':row.status,...d,paid,balance,dueNow:Math.min(balance,Math.max(0,depositAmount-paid)||balance),payments:publicView?payments.map(p=>({amount:p.amount,method:p.method,created_at:p.created_at})):payments,updatedAt:row.updated_at};}
async function fromToken(db,token){const m=/^([a-f0-9-]{36})\.([a-f0-9]{64})$/.exec(token||'');if(!m)return null;const access=await db.prepare('SELECT token_hash FROM invoice_access WHERE document_id = ?').bind(m[1]).first();if(!access||access.token_hash!==await hash(m[2]))return null;return db.prepare("SELECT * FROM business_documents WHERE id = ? AND kind = 'invoice'").bind(m[1]).first();}
export async function commerceRoutes(request,env,url,isAdmin){const path=url.pathname,handled=path.startsWith('/api/admin/invoices')||path.startsWith('/api/admin/customers')||path.startsWith('/api/invoice');if(!handled)return null;
 if(path.startsWith('/api/admin/')&&!isAdmin(request))return json({error:'Owner sign-in required'},403);
 if(!['GET','POST'].includes(request.method))return json({error:'Method not allowed'},405);
 if(request.method==='POST'&&request.headers.get('Origin')!==url.origin)return json({error:'Invalid request origin'},403);
 if(!env.DB)return json({error:'Storage is unavailable'},503);
 try{const db=env.DB;
 if(path==='/api/admin/customers'&&request.method==='GET')return json({customers:(await db.prepare('SELECT * FROM customers ORDER BY name LIMIT 3000').all()).results});
 if(path==='/api/admin/customers'&&request.method==='POST'){const v=await input(request),rows=Array.isArray(v.customers)?v.customers:[v];if(!rows.length||rows.length>1000)throw Error('Import up to 1000 customers at a time');const queries=[];for(const c of rows){const name=clean(c.name,120),email=clean(c.email,254).toLowerCase();if(name.length<2||email&&!/^\S+@\S+\.\S+$/.test(email))throw Error('Check customer name and email');let id=c.id;if(id&&!uuid(id))throw Error('Invalid customer');if(!id&&email)id=(await db.prepare('SELECT id FROM customers WHERE email = ? LIMIT 1').bind(email).first())?.id;id=id||crypto.randomUUID();queries.push(db.prepare('INSERT INTO customers (id,name,email,phone,business,address,notes,updated_at) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,email=excluded.email,phone=excluded.phone,business=excluded.business,address=excluded.address,notes=excluded.notes,updated_at=excluded.updated_at').bind(id,name,email,clean(c.phone,60),clean(c.business,160),clean(c.address,1000),clean(c.notes,2000),now()));}for(let i=0;i<queries.length;i+=80)await db.batch(queries.slice(i,i+80));return json({saved:true,count:rows.length});}
 if(path==='/api/admin/invoices'&&request.method==='GET'){const rows=(await db.prepare("SELECT * FROM business_documents WHERE kind = 'invoice' ORDER BY updated_at DESC LIMIT 300").all()).results;return json({invoices:await Promise.all(rows.map(r=>summary(db,r))),providers:[{id:'card',label:'Credit / debit card',connected:false},{id:'paypal',label:'PayPal',connected:false}]});}
 if(path==='/api/admin/invoices/save'&&request.method==='POST'){const v=await input(request);const id=v.id||crypto.randomUUID();if(!uuid(id)||!['draft','sent','cancelled'].includes(v.status))throw Error('Check invoice status');const old=await db.prepare('SELECT * FROM business_documents WHERE id = ?').bind(id).first();if(old&&old.kind!=='invoice')throw Error('Invalid document');const oldData=old?JSON.parse(old.data):null;if((oldData?.revision||0)!==(v.expectedRevision||0))return json({error:'Invoice changed elsewhere. Reopen it.'},409);let customer;if(v.customerId){customer=await db.prepare('SELECT * FROM customers WHERE id = ?').bind(v.customerId).first();if(!customer)throw Error('Choose a customer');}else customer={name:clean(v.customer,120),email:clean(v.email,254),business:clean(v.business,160),address:clean(v.address,1000),phone:clean(v.phone,60)};if(!customer.name)throw Error('Add a customer');const totals=invoiceTotals(v);if(old){const paid=(await db.prepare('SELECT COALESCE(SUM(amount),0) AS n FROM invoice_payments WHERE document_id = ?').bind(id).first()).n;if(paid&&(JSON.stringify(totals.items)!==JSON.stringify(oldData.items)||totals.total!==oldData.total||totals.tax!==oldData.tax||JSON.stringify(totals.discount)!==JSON.stringify(oldData.discount)||JSON.stringify(totals.deposit)!==JSON.stringify(oldData.deposit)||customer.name!==oldData.customer||customer.email!==oldData.email))throw Error('Paid invoice amounts and customer are locked. Create an adjustment invoice.');}
 const profile=await db.prepare("SELECT value FROM site_settings WHERE key='business'").first();
 const data={...totals,issueDate:oldData?.issueDate||clean(v.issueDate,10)||now().slice(0,10),terms:clean(v.terms,3000),seller:oldData?.seller||(profile?JSON.parse(profile.value):{name:'Satin Graphic',email:'info@satingraphic.ca'}),sourceQuoteId:oldData?.sourceQuoteId||null,customerId:customer.id||null,customer:customer.name,email:customer.email,business:customer.business,address:customer.address,phone:customer.phone,title:clean(v.title,200)||'Invoice',dueDate:clean(v.dueDate,10),notes:clean(v.notes,3000),revision:(oldData?.revision||0)+1};if(data.issueDate&&!/^\d{4}-\d{2}-\d{2}$/.test(data.issueDate))throw Error('Check issue date');if(data.dueDate&&!/^\d{4}-\d{2}-\d{2}$/.test(data.dueDate))throw Error('Check due date');
 const result=old?await db.prepare("UPDATE business_documents SET status = ?,data = ?,updated_at = ? WHERE id = ? AND kind = 'invoice' AND data = ?").bind(v.status,JSON.stringify(data),now(),id,old.data).run():await db.prepare("INSERT INTO business_documents (id,kind,status,data,updated_at) VALUES (?,'invoice',?,?,?) ON CONFLICT(id) DO NOTHING").bind(id,v.status,JSON.stringify(data),now()).run();if(!result.meta.changes)return json({error:'Invoice changed elsewhere. Reopen it.'},409);return json({saved:true,id,revision:data.revision});}
 if(path==='/api/admin/invoices/link'&&request.method==='POST'){const v=await input(request);if(!uuid(v.id))throw Error('Invalid invoice');const row=await db.prepare("SELECT * FROM business_documents WHERE id = ? AND kind = 'invoice'").bind(v.id).first();if(!row||row.status==='draft'||row.status==='cancelled')throw Error('Mark invoice sent before creating its link');let access=await db.prepare('SELECT token FROM invoice_access WHERE document_id = ?').bind(v.id).first();if(!access){const token=hex(crypto.getRandomValues(new Uint8Array(32)));await db.prepare('INSERT INTO invoice_access (document_id,token,token_hash,created_at) VALUES (?,?,?,?) ON CONFLICT(document_id) DO NOTHING').bind(v.id,token,await hash(token),now()).run();access=await db.prepare('SELECT token FROM invoice_access WHERE document_id = ?').bind(v.id).first();}return json({url:url.origin+'/pay/invoice/?token='+v.id+'.'+access.token});}
 if(path==='/api/admin/invoices/payment'&&request.method==='POST'){const v=await input(request);if(!uuid(v.id)||!uuid(v.paymentId)||!['cash','e-transfer','bank','other'].includes(v.method))throw Error('Check payment details');const row=await db.prepare("SELECT * FROM business_documents WHERE id = ? AND kind = 'invoice'").bind(v.id).first();if(!row||['draft','cancelled'].includes(row.status))throw Error('Invoice is not payable');const cents=amount(Number(v.amount));if(!cents)throw Error('Enter a positive amount');const existing=await db.prepare('SELECT document_id,amount,method FROM invoice_payments WHERE id = ?').bind(v.paymentId).first();if(existing){if(existing.document_id!==v.id||existing.amount!==cents||existing.method!==v.method)throw Error('Payment reference already used');return json({saved:true});}const result=await db.prepare("INSERT INTO invoice_payments (id,document_id,amount,method,reference,created_at) SELECT ?,?,?,?,?,? WHERE ? <= (SELECT CAST(json_extract(data,'$.total') AS INTEGER) FROM business_documents WHERE id = ? AND kind = 'invoice' AND status NOT IN ('draft','cancelled')) - (SELECT COALESCE(SUM(amount),0) FROM invoice_payments WHERE document_id = ?) ON CONFLICT(id) DO NOTHING").bind(v.paymentId,v.id,cents,v.method,clean(v.reference,200),now(),cents,v.id,v.id).run();if(!result.meta.changes)throw Error('Payment exceeds the remaining balance');return json({saved:true});}
 if(path==='/api/invoice'&&request.method==='GET'){const row=await fromToken(db,url.searchParams.get('token'));if(!row||row.status==='draft')return json({error:'Invoice not found'},404);return json({invoice:await summary(db,row,true),providers:[{id:'card',label:'Credit / debit card',connected:false},{id:'paypal',label:'PayPal',connected:false}]});}
 if(path==='/api/invoice/checkout'&&request.method==='POST'){const v=await input(request),row=await fromToken(db,v.token);if(!row||['draft','cancelled'].includes(row.status))return json({error:'Invoice is not payable'},404);const inv=await summary(db,row);if(!inv.balance)return json({error:'Invoice already paid'},409);if(!['deposit','balance'].includes(v.stage)||!['card','paypal'].includes(v.provider))throw Error('Choose a payment method');return json({error:'Online payment is not connected yet. Contact Satin Graphic to arrange payment.',amount:v.stage==='deposit'?inv.dueNow:inv.balance,currency:'CAD',code:'provider_not_connected'},503);}
 return json({error:'Not found'},404);
 }catch(e){console.error('Commerce operation failed',e?.message);return json({error:e?.message||'Could not save'},400);}
}
